// #781: the admin transaction row's rate and reference rate are shown per the row's unit, through
// the one formatter `formatRate(rate, unitSize, code)` (`web/src/shared/ui/rate.ts`).
// Written before the implementation by the ticket author (claude/e5ab6c). Do not edit, delete or
// weaken; add tests in a file of your own.
//
// Design `docs/design/blueprint/rates.md`:
// - §3.3 "On the wire": the row's `rate` is the 8-place string the database holds; one web
//   formatter, `formatRate`, shows at least 2 and at most 8 places with trailing zeros trimmed,
//   then `/ <unit_size> <code>` when the unit is above 1. No screen formats a rate itself, and a
//   second formatter is a per-variant copy (forbidden);
// - §4.9 R1 (v3 views speak per unit), R3 (only the v2-compat wire is per 1).
//
// Every admin screen that shows a `TransactionRow`'s rate does it through two parts:
// `TransactionTable` (`@ <rate>` under the amount; used by Transactions and the Overview) and
// `TransactionDetail` (`เรท`, `เรทอ้างอิง`; opened from Transactions, Slips, Customers, the
// Overview and Reports). Both are pinned here, with the literal strings:
// - KRW 25.12345678 per 1000 → `25.12345678 / 1000 KRW` (today `25.1235`, no unit);
//   reference 25 per 1000 (`"25.00000000"`) → `25.00 / 1000 KRW`;
// - USD 32.1 per 1 (`"32.10000000"`) → `32.10`; reference 32.5 → `32.50`;
// - JPY 23.5 per 100 (`"23.50000000"`) → `23.50 / 100 JPY`.
// `TransactionRate.formatter.test.tsx` proves the parts call `formatRate` with the row's own
// rate, unit and currency, and print its result as is.
//
// No server is involved: the rows are what the server sends after #781. Nothing here skips.
//
// Signatures and fields assumed:
// - [required] `TransactionRow.unitSize: string` (`web/src/shared/api/generated/transaction_row.ts`,
//   generated by ts-rs from `api/src/presentation/dto/v3/transaction_row.rs`; until it is
//   regenerated, the `unitSize` in the rows below is the one `npm run typecheck` error this file
//   adds);
// - `formatRate(rate: string, unitSize: number | string, code: string): string` as merged;
// - `TransactionTable({ rows, onOpen })`, `TransactionDetail({ api, branch, row, onClose })` as
//   merged, the rate under the amount in `.rate`, the detail as `<dt>`/`<dd>` pairs.
import { afterEach, describe, expect, it } from 'vitest';
import { render } from 'solid-js/web';
import type { JSX } from 'solid-js';
import type { ApiClient, ViewAnswer } from '../../../shared/api/client';
import { makeTransactionRow, type TransactionRow } from '../../../shared/testing/fixtures';
import { setLang } from '../../../shared/i18n';
import { th } from './i18n';
import { TransactionDetail } from './TransactionDetail';
import { TransactionTable } from './TransactionTable';

const sources = import.meta.glob<string>(['./TransactionTable.tsx', './TransactionDetail.tsx'], {
  query: '?raw',
  import: 'default',
  eager: true,
});

function row(over: Partial<TransactionRow> = {}) {
  return makeTransactionRow({
    id: 'RE4-KRW',
    date: '2026-10-06',
    created: '2026-10-06T03:04:05.000Z',
    type: 'BUY',
    currency: 'KRW',
    amount: '100000.00',
    rate: '25.12345678',
    unitSize: '1000',
    principal: '2512.35',
    fee: '0.00',
    bankFee: '0.00',
    settlement: '2512.35',
    method: 'Cash',
    customer: 'Somchai',
    customerId: 'CU-RE4-KRW',
    staff: 'owner',
    status: 'COMPLETED',
    notes: null,
    cancelReason: null,
    shiftId: 'SH-1',
    referenceRate: '25.00000000',
    referenceValue: '2500.00',
    referenceSpread: '-12.35',
    referencePercent: '-0.494000',
    paymentRef: null,
    slipUrl: null,
    ...over,
  });
}

const KRW = row();
const USD = row({
  id: 'RE4-USD',
  currency: 'USD',
  amount: '100.00',
  rate: '32.10000000',
  unitSize: '1',
  principal: '3210.00',
  settlement: '3210.00',
  referenceRate: '32.50000000',
  referenceValue: '3250.00',
  referenceSpread: '40.00',
  referencePercent: '1.230769',
});
const JPY = row({
  id: 'RE4-JPY',
  type: 'SELL',
  currency: 'JPY',
  amount: '1000.00',
  rate: '23.50000000',
  unitSize: '100',
  principal: '235.00',
  settlement: '235.00',
  referenceRate: '23.01000000',
  referenceValue: '230.10',
  referenceSpread: '4.90',
  referencePercent: '2.129509',
});

/** The detail reads its receipt from `transaction_documents`; the answer never comes here. */
function quietApi(): ApiClient {
  return {
    view: () => new Promise<ViewAnswer<unknown>>(() => {}),
    page: async () => {
      throw new Error('the detail reads no page');
    },
    post: async () => {
      throw new Error('the detail writes nothing');
    },
  } as unknown as ApiClient;
}

let dispose: (() => void) | undefined;
let root: HTMLElement;

function mount(fn: () => JSX.Element): HTMLElement {
  root = document.createElement('div');
  document.body.appendChild(root);
  dispose = render(fn, root);
  return root;
}

afterEach(() => {
  dispose?.();
  dispose = undefined;
  root?.remove();
  setLang('th');
});

/** The `.rate` line under the amount of the table row for `id`. */
function tableRate(el: HTMLElement, id: string): string {
  const tr = [...el.querySelectorAll('tbody tr')].find((r) => (r.textContent ?? '').includes(id));
  expect(tr, `a table row for ${id}`).toBeDefined();
  const rate = tr!.querySelector('.rate');
  expect(rate, `${id}: a .rate line`).not.toBeNull();
  return (rate!.textContent ?? '').trim();
}

/** The `<dd>` after the `<dt>` named `label`, or `undefined` when there is none. */
function field(el: HTMLElement, label: string): string | undefined {
  const dt = [...el.querySelectorAll('dt')].find((d) => (d.textContent ?? '').trim() === label);
  if (!dt) return undefined;
  const dd = dt.nextElementSibling;
  expect(dd?.tagName, `${label}: a dd follows`).toBe('DD');
  return (dd!.textContent ?? '').trim();
}

describe('#781 TransactionTable: the rate per its unit through formatRate', () => {
  it('KRW per 1000, USD per 1 and JPY per 100, as formatRate prints them', () => {
    const el = mount(() => <TransactionTable rows={[KRW, USD, JPY]} onOpen={() => {}} />);
    expect(tableRate(el, 'RE4-KRW')).toBe('@ 25.12345678 / 1000 KRW');
    expect(tableRate(el, 'RE4-USD')).toBe('@ 32.10');
    expect(tableRate(el, 'RE4-JPY')).toBe('@ 23.50 / 100 JPY');
  });

  it('never the 4-place cut nor the raw 8-place string', () => {
    const el = mount(() => <TransactionTable rows={[KRW, USD]} onOpen={() => {}} />);
    const text = el.textContent ?? '';
    expect(text).not.toContain('25.1235');
    expect(text).not.toContain('32.10000000');
    expect(text).not.toContain('32.1000');
  });
});

describe('#781 TransactionDetail: the rate and the reference rate per the row unit', () => {
  it('KRW: เรท 25.12345678 / 1000 KRW, เรทอ้างอิง 25.00 / 1000 KRW', () => {
    const el = mount(() => <TransactionDetail api={quietApi()} branch="MAIN" row={KRW} onClose={() => {}} />);
    expect(field(el, th.detailRate)).toBe('25.12345678 / 1000 KRW');
    expect(field(el, th.detailRefRate)).toBe('25.00 / 1000 KRW');
  });

  it('USD: เรท 32.10, เรทอ้างอิง 32.50', () => {
    const el = mount(() => <TransactionDetail api={quietApi()} branch="MAIN" row={USD} onClose={() => {}} />);
    expect(field(el, th.detailRate)).toBe('32.10');
    expect(field(el, th.detailRefRate)).toBe('32.50');
  });

  it('JPY per 100: เรท 23.50 / 100 JPY, เรทอ้างอิง 23.01 / 100 JPY', () => {
    const el = mount(() => <TransactionDetail api={quietApi()} branch="MAIN" row={JPY} onClose={() => {}} />);
    expect(field(el, th.detailRate)).toBe('23.50 / 100 JPY');
    expect(field(el, th.detailRefRate)).toBe('23.01 / 100 JPY');
  });

  it('a row with no reference (recorded before publications): its own rate, no reference row', () => {
    const mid = row({
      id: 'RE4-MID',
      amount: '1000.00',
      rate: '25.12500000',
      principal: '25.13',
      settlement: '25.13',
      referenceRate: null,
      referenceValue: null,
      referenceSpread: null,
      referencePercent: null,
    });
    const el = mount(() => <TransactionDetail api={quietApi()} branch="MAIN" row={mid} onClose={() => {}} />);
    expect(field(el, th.detailRate)).toBe('25.125 / 1000 KRW');
    expect(field(el, th.detailRefRate)).toBeUndefined();
  });
});

describe('#781 the parts format no rate themselves (§3.3: one formatter)', () => {
  const own = Object.entries(sources);

  it('both parts are read', () => {
    expect(own.map(([p]) => p).sort()).toEqual(['./TransactionDetail.tsx', './TransactionTable.tsx']);
  });

  it('each imports formatRate from shared/ui/rate and declares no formatter of its own', () => {
    for (const [path, text] of own) {
      expect(text, path).toMatch(/import\s*\{[^}]*\bformatRate\b[^}]*\}\s*from\s*['"]\.\.\/\.\.\/\.\.\/shared\/ui\/rate['"]/);
      expect(text, path).not.toMatch(/(?:function|const|let|var)\s+formatRate\b/);
    }
  });

  it('no toFixed, parseFloat, Number(…) or Intl.NumberFormat in either part', () => {
    for (const [path, text] of own) {
      expect(text, path).not.toMatch(/\.toFixed\s*\(|\bparseFloat\s*\(|\bNumber\s*\(|Intl\.NumberFormat/);
    }
  });
});
